/** void SpriteCB_MoveMonForInfoScreen(struct Sprite *sprite) */
export function SpriteCB_MoveMonForInfoScreen(sprite: any): any {
  sprite.oam.priority = 0;
      sprite.oam.affineMode = ST_OAM_AFFINE_OFF;
      sprite.x2 = 0;
      sprite.y2 = 0;
      if (sprite.x != MON_PAGE_X || sprite.y != MON_PAGE_Y)
      {
          if (sprite.x > MON_PAGE_X)
              sprite.x--;
          if (sprite.x < MON_PAGE_X)
              sprite.x++;

          if (sprite.y > MON_PAGE_Y)
              sprite.y--;
          if (sprite.y < MON_PAGE_Y)
              sprite.y++;
      }
      else
      {
          sprite.callback = SpriteCB_EndMoveMonForInfoScreen;
      }
}

/** static void SpriteCB_PokedexListMonSprite(struct Sprite *sprite) */
export function SpriteCB_PokedexListMonSprite(sprite: any): any {
  let monId: any = sprite.data[1];

      if (sPokedexView.currentPage != PAGE_MAIN && sPokedexView.currentPage != PAGE_SEARCH_RESULTS)
      {
          FreeAndDestroyMonPicSprite(sPokedexView.monSpriteIds[monId]);
          sPokedexView.monSpriteIds[monId] = 0xFFFF;
      }
      else
      {
          let _var: any = null;
          sprite.y2 = gSineTable[sprite.data[5]] * 76 / 256;
          _var = SAFE_DIV(_0x10000, gSineTable[sprite.data[5] + 64]);
          if (_var > 0xFFFF)
              _var = 0xFFFF;
          SetOamMatrix(sprite.data[1] + 1, _0x100, 0, 0, _var);
          sprite.oam.matrixNum = monId + 1;

          if (sprite.data[5] > -64 && sprite.data[5] < 64)
          {
              sprite.invisible = FALSE;
              sprite.data[0] = 1;
          }
          else
          {
              sprite.invisible = TRUE;
          }

          if ((sprite.data[5] <= -64 || sprite.data[5] >= 64) && sprite.data[0] != 0)
          {
              FreeAndDestroyMonPicSprite(sPokedexView.monSpriteIds[monId]);
              sPokedexView.monSpriteIds[monId] = 0xFFFF;
          }
      }
}

/** static void SpriteCB_Scrollbar(struct Sprite *sprite) */
