/** static void SpriteCB_RotatingPokeBall(struct Sprite *sprite) */
export function SpriteCB_RotatingPokeBall(sprite: any): any {
  if (sPokedexView.currentPage != PAGE_MAIN && sPokedexView.currentPage != PAGE_SEARCH_RESULTS)
      {
          DestroySprite(sprite);
      }
      else
      {
          let val: any = null;
          let r3: any = null;
          let r0: any = null;

          val = sPokedexView.pokeBallRotation + sprite.data[1];
          r3 = gSineTable[val];
          r0 = gSineTable[val + 64];
          SetOamMatrix(sprite.data[0], r0, r3, -r3, r0);

          val = sPokedexView.pokeBallRotation + (sprite.data[1] + 64);
          r3 = gSineTable[val];
          r0 = gSineTable[val + 64];
          sprite.x2 = r0 * 40 / 256;
          sprite.y2 = r3 * 40 / 256;
      }
}

/** static void SpriteCB_DexListStartMenuCursor(struct Sprite *sprite) */
export function SpriteCB_DexListStartMenuCursor(sprite: any): any {
  if (sPokedexView.currentPage != PAGE_MAIN && sPokedexView.currentPage != PAGE_SEARCH_RESULTS)
      {
          DestroySprite(sprite);
      }
      else
      {
          let r1: any = sPokedexView.currentPage == PAGE_MAIN ? 80 : 96;

          if (sPokedexView.menuIsOpen && sPokedexView.menuY == r1)
          {
              sprite.invisible = FALSE;
              sprite.y2 = sPokedexView.menuCursorPos * 16;
              sprite.x2 = gSineTable[sprite.data[2]] / 64;
              sprite.data[2] += 8;
          }
          else
          {
              sprite.invisible = TRUE;
          }
      }
}

