/** static u8 LoadInfoScreen(struct PokedexListItem *item, u8 monSpriteId) */
export function LoadInfoScreen(item: any, monSpriteId: any): any {
  let taskId: any = null;

      sPokedexListItem = item;
      taskId = CreateTask(Task_LoadInfoScreen, 0);
      gTasks[taskId].tScrolling = FALSE;
      gTasks[taskId].tMonSpriteDone = TRUE;  
      gTasks[taskId].tBgLoaded = FALSE;
      gTasks[taskId].tSkipCry = FALSE;
      gTasks[taskId].tMonSpriteId = monSpriteId;
      gTasks[taskId].tTrainerSpriteId = SPRITE_NONE;
      ResetBgsAndClearDma3BusyFlags(0);
      InitBgsFromTemplates(0, sInfoScreen_BgTemplate, ARRAY_COUNT(sInfoScreen_BgTemplate));
      SetBgTilemapBuffer(3, AllocZeroed(BG_SCREEN_SIZE));
      SetBgTilemapBuffer(2, AllocZeroed(BG_SCREEN_SIZE));
      SetBgTilemapBuffer(1, AllocZeroed(BG_SCREEN_SIZE));
      SetBgTilemapBuffer(0, AllocZeroed(BG_SCREEN_SIZE));
      InitWindows(sInfoScreen_WindowTemplates);
      DeactivateAllTextPrinters();

      return taskId;
}

/** static bool8 IsInfoScreenScrolling(u8 taskId) */
export function IsInfoScreenScrolling(taskId: any): any {
  if (!gTasks[taskId].tScrolling && gTasks[taskId].func == Task_HandleInfoScreenInput)
          return FALSE;
      else
          return TRUE;
}

/** static u8 StartInfoScreenScroll(struct PokedexListItem *item, u8 taskId) */
export function StartInfoScreenScroll(item: any, taskId: any): any {
  sPokedexListItem = item;
      gTasks[taskId].tScrolling = TRUE;
      gTasks[taskId].tMonSpriteDone = FALSE;
      gTasks[taskId].tBgLoaded = FALSE;
      gTasks[taskId].tSkipCry = FALSE;
      return taskId;
}

/** static void Task_LoadInfoScreen(u8 taskId) */
export function Task_LoadInfoScreen(taskId: any): any {
  switch (gMain.state)
      {
      case 0:
      default:
          if (!gPaletteFade.active)
          {
              let r2: any = null;

              sPokedexView.currentPage = PAGE_INFO;
              gPokedexVBlankCB = gMain.vblankCallback;
              SetVBlankCallback(NULL);
              r2 = 0;
              if (gTasks[taskId].tMonSpriteDone)
                  r2 += DISPCNT_OBJ_ON;
              if (gTasks[taskId].tBgLoaded)
                  r2 |= DISPCNT_BG1_ON;
              ResetOtherVideoRegisters(r2);
              gMain.state = 1;
          }
          break;
      case 1:
          DecompressAndLoadBgGfxUsingHeap(3, gPokedexMenu_Gfx, _0x2000, 0, 0);
          CopyToBgTilemapBuffer(3, gPokedexInfoScreen_Tilemap, 0, 0);
          FillWindowPixelBuffer(WIN_INFO, PIXEL_FILL(0));
          PutWindowTilemap(WIN_INFO);
          PutWindowTilemap(WIN_FOOTPRINT);
          DrawFootprint(WIN_FOOTPRINT, sPokedexListItem.dexNum);
          CopyWindowToVram(WIN_FOOTPRINT, COPYWIN_GFX);
          gMain.state++;
          break;
      case 2:
          LoadScreenSelectBarMain(0xD);
          HighlightScreenSelectBarItem(sPokedexView.selectedScreen, 0xD);
          LoadPokedexBgPalette(sPokedexView.isSearchResults);
          gMain.state++;
          break;
      case 3:
          gMain.state++;
          break;
      case 4:
          PrintMonInfo(sPokedexListItem.dexNum, sPokedexView.dexMode == DEX_MODE_HOENN ? FALSE : TRUE, sPokedexListItem.owned, 0);
          if (!sPokedexListItem.owned)
              LoadPalette(gPlttBufferUnfaded[BG_PLTT_ID(0) + 1], BG_PLTT_ID(3) + 1, PLTT_SIZEOF(16 - 1));
          CopyWindowToVram(WIN_INFO, COPYWIN_FULL);
          CopyBgTilemapBufferToVram(1);
          CopyBgTilemapBufferToVram(2);
          CopyBgTilemapBufferToVram(3);
          gMain.state++;
          break;
      case 5:
          if (!gTasks[taskId].tMonSpriteDone)
          {
              gTasks[taskId].tMonSpriteId = CreateMonSpriteFromNationalDexNumber(sPokedexListItem.dexNum, MON_PAGE_X, MON_PAGE_Y, 0);
              gSprites[gTasks[taskId].tMonSpriteId].oam.priority = 0;
          }
          gMain.state++;
          break;
      case 6:
          {
              let preservedPalettes: any = 0;

              if (gTasks[taskId].tBgLoaded)
                  preservedPalettes = _0x14;  
              if (gTasks[taskId].tMonSpriteDone)
                  preservedPalettes |= (1 << (gSprites[gTasks[taskId].tMonSpriteId].oam.paletteNum + 16));
              BeginNormalPaletteFade(~preservedPalettes, 0, 16, 0, RGB_BLACK);
              SetVBlankCallback(gPokedexVBlankCB);
              gMain.state++;
          }
          break;
      case 7:
          SetGpuReg(REG_OFFSET_BLDCNT, 0);
          SetGpuReg(REG_OFFSET_BLDALPHA, 0);
          SetGpuReg(REG_OFFSET_BLDY, 0);
          SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_1D_MAP | DISPCNT_OBJ_ON);
          HideBg(0);
          ShowBg(1);
          ShowBg(2);
          ShowBg(3);
          gMain.state++;
          break;
      case 8:
          if (!gPaletteFade.active)
          {
              gMain.state++;
              if (!gTasks[taskId].tSkipCry)
              {
                  StopCryAndClearCrySongs();
                  PlayCry_NormalNoDucking(NationalPokedexNumToSpecies(sPokedexListItem.dexNum), 0, CRY_VOLUME_RS, CRY_PRIORITY_NORMAL);
              }
              else
              {
                  gMain.state++;
              }
          }
          break;
      case 9:
          if (!IsCryPlayingOrClearCrySongs())
              gMain.state++;
          break;
      case 10:
          gTasks[taskId].tScrolling = FALSE;
          gTasks[taskId].tMonSpriteDone = FALSE;  
          gTasks[taskId].tBgLoaded = TRUE;
          gTasks[taskId].tSkipCry = TRUE;
          gTasks[taskId].func = Task_HandleInfoScreenInput;
          gMain.state = 0;
          break;
      }
}

/** static void FreeInfoScreenWindowAndBgBuffers(void) */
export function FreeInfoScreenWindowAndBgBuffers(): any {
  let tilemapBuffer: any = null;

      FreeAllWindowBuffers();
      tilemapBuffer = GetBgTilemapBuffer(0);
      if (tilemapBuffer)
          Free(tilemapBuffer);
      tilemapBuffer = GetBgTilemapBuffer(1);
      if (tilemapBuffer)
          Free(tilemapBuffer);
      tilemapBuffer = GetBgTilemapBuffer(2);
      if (tilemapBuffer)
          Free(tilemapBuffer);
      tilemapBuffer = GetBgTilemapBuffer(3);
      if (tilemapBuffer)
          Free(tilemapBuffer);
}

/** static void Task_HandleInfoScreenInput(u8 taskId) */
export function Task_HandleInfoScreenInput(taskId: any): any {
  if (gTasks[taskId].tScrolling)
      {
           
          BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
          gTasks[taskId].func = Task_LoadInfoScreenWaitForFade;
          PlaySE(SE_DEX_SCROLL);
          return;
      }
      if (JOY_NEW(B_BUTTON))
      {
          BeginNormalPaletteFade(PALETTES_ALL, 0, 0, 16, RGB_BLACK);
          gTasks[taskId].func = Task_ExitInfoScreen;
          PlaySE(SE_PC_OFF);
          return;
      }
      if (JOY_NEW(A_BUTTON))
      {
          switch (sPokedexView.selectedScreen)
          {
          case AREA_SCREEN:
              BeginNormalPaletteFade(PALETTES_ALL & ~(_0x14), 0, 0, 16, RGB_BLACK);
              sPokedexView.screenSwitchState = 1;
              gTasks[taskId].func = Task_SwitchScreensFromInfoScreen;
              PlaySE(SE_PIN);
              break;
          case CRY_SCREEN:
              BeginNormalPaletteFade(PALETTES_ALL & ~(_0x14), 0, 0, _0x10, RGB_BLACK);
              sPokedexView.screenSwitchState = 2;
              gTasks[taskId].func = Task_SwitchScreensFromInfoScreen;
              PlaySE(SE_PIN);
              break;
          case SIZE_SCREEN:
              if (!sPokedexListItem.owned)
              {
                  PlaySE(SE_FAILURE);
              }
              else
              {
                  BeginNormalPaletteFade(PALETTES_ALL & ~(_0x14), 0, 0, _0x10, RGB_BLACK);
                  sPokedexView.screenSwitchState = 3;
                  gTasks[taskId].func = Task_SwitchScreensFromInfoScreen;
                  PlaySE(SE_PIN);
              }
              break;
          case CANCEL_SCREEN:
              BeginNormalPaletteFade(PALETTES_ALL, 0, 0, _0x10, RGB_BLACK);
              gTasks[taskId].func = Task_ExitInfoScreen;
              PlaySE(SE_PC_OFF);
              break;
          }
          return;
      }
      if ((JOY_NEW(DPAD_LEFT)
       || (JOY_NEW(L_BUTTON) && gSaveBlock2Ptr.optionsButtonMode == OPTIONS_BUTTON_MODE_LR))
       && sPokedexView.selectedScreen > 0)
      {
          sPokedexView.selectedScreen--;
          HighlightScreenSelectBarItem(sPokedexView.selectedScreen, 0xD);
          PlaySE(SE_DEX_PAGE);
          return;
      }
      if ((JOY_NEW(DPAD_RIGHT)
       || (JOY_NEW(R_BUTTON) && gSaveBlock2Ptr.optionsButtonMode == OPTIONS_BUTTON_MODE_LR))
       && sPokedexView.selectedScreen < CANCEL_SCREEN)
      {
          sPokedexView.selectedScreen++;
          HighlightScreenSelectBarItem(sPokedexView.selectedScreen, 0xD);
          PlaySE(SE_DEX_PAGE);
          return;
      }
}

/** static void Task_SwitchScreensFromInfoScreen(u8 taskId) */
export function Task_SwitchScreensFromInfoScreen(taskId: any): any {
  if (!gPaletteFade.active)
      {
          FreeAndDestroyMonPicSprite(gTasks[taskId].tMonSpriteId);
          switch (sPokedexView.screenSwitchState)
          {
          case 1:
          default:
              gTasks[taskId].func = Task_LoadAreaScreen;
              break;
          case 2:
              gTasks[taskId].func = Task_LoadCryScreen;
              break;
          case 3:
              gTasks[taskId].func = Task_LoadSizeScreen;
              break;
          }
      }
}

