/** bool16 HasAllHoennMons(void) */
export function HasAllHoennMons(): any {
  let i: any = null;

       
      for (i = 0; i < HOENN_DEX_COUNT - 2; i++)
      {
          if (!GetSetPokedexFlag(HoennToNationalOrder(i + 1), FLAG_GET_CAUGHT))
              return FALSE;
      }
      return TRUE;
}

